contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Take an amount to deposit; ensure this test contract has sufficient Ether
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record C's balance before interaction
        uint before = address(c).balance;

        // perform deposit of 'amount' into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // record C's balance immediately after deposit
        uint afterDeposit = address(c).balance;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record C's balance after the withdrawAll attempt
        uint afterWithdraw = address(c).balance;

        // General rule: withdrawAll cannot increase C's balance compared to immediately after deposit
        assert(afterWithdraw <= afterDeposit);
    }

    receive() external payable {}
}

